  const list = intervals.map(([s, e]) => [s, e]);
  let changed = true;
  while (changed) {   // repeat until no two intervals overlap
    changed = false;
    for (let i = 0; i < list.length && !changed; i++) {
      for (let j = i + 1; j < list.length && !changed; j++) {
        const [a, b] = [list[i], list[j]];
        if (a[0] <= b[1] && b[0] <= a[1]) {   // they overlap
          list[i] = [Math.min(a[0], b[0]), Math.max(a[1], b[1])];
          list.splice(j, 1);
          changed = true;
        }
      }
    }
  }
  return list.sort((a, b) => a[0] - b[0]);
