def merge(intervals):
    merged = [list(it) for it in intervals]
    changed = True
    while changed:   # repeat until no two intervals overlap
        changed = False
        for i in range(len(merged)):
            for j in range(i + 1, len(merged)):
                a, b = merged[i], merged[j]
                if a[0] <= b[1] and b[0] <= a[1]:   # they overlap
                    merged[i] = [min(a[0], b[0]), max(a[1], b[1])]
                    merged.pop(j)
                    changed = True
                    break
            if changed:
                break
    return sorted(merged)

class Solution {
    public int[][] merge(int[][] intervals) {
        List<int[]> list = new ArrayList<>();
        for (int[] it : intervals) list.add(it.clone());
        boolean changed = true;
        while (changed) {   // repeat until no two intervals overlap
            changed = false;
            for (int i = 0; i < list.size() && !changed; i++) {
                for (int j = i + 1; j < list.size() && !changed; j++) {
                    int[] a = list.get(i), b = list.get(j);
                    if (a[0] <= b[1] && b[0] <= a[1]) {   // they overlap
                        list.set(i, new int[]{Math.min(a[0], b[0]), Math.max(a[1], b[1])});
                        list.remove(j);
                        changed = true;
                    }
                }
            }
        }
        list.sort((a, b) -> Integer.compare(a[0], b[0]));
        return list.toArray(new int[0][]);
    }
}

class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        vector<vector<int>> list = intervals;
        bool changed = true;
        while (changed) {   // repeat until no two intervals overlap
            changed = false;
            for (int i = 0; i < (int)list.size() && !changed; i++) {
                for (int j = i + 1; j < (int)list.size() && !changed; j++) {
                    if (list[i][0] <= list[j][1] && list[j][0] <= list[i][1]) {   // they overlap
                        int start = min(list[i][0], list[j][0]);
                        int end = max(list[i][1], list[j][1]);
                        list[i] = {start, end};
                        list.erase(list.begin() + j);
                        changed = true;
                    }
                }
            }
        }
        sort(list.begin(), list.end());
        return list;
    }
};

