class Solution {
    public int[][] merge(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));   // 1. sort by start
        int write = 0;                                                   // intervals[0..write] is the answer so far
        for (int read = 1; read < intervals.length; read++) {
            if (intervals[read][0] <= intervals[write][1]) {
                intervals[write][1] = Math.max(intervals[write][1], intervals[read][1]);   // overlap: extend
            } else {
                intervals[++write] = intervals[read];                                     // gap: start a new one
            }
        }
        return Arrays.copyOf(intervals, write + 1);   // Java arrays can't shrink: return the first write + 1
    }
}

